/**
 * User-facing messages keyed by problem code.
 *
 * Each entry follows the error pattern in `apps/web/docs/ux-writing.md`:
 * `message` says what happened and why, `action` says what to do next.
 * Neither repeats the code: `ProblemMessage` shows the code, the server
 * detail and the request id under "Details" for support.
 *
 * Codes come from what the web app renders and from the services' error
 * tables (purchasing, receiving, payables, sales, inventory, ledger, party, tax and product).
 * A code without an entry falls back to the server's title or detail.
 */
import { translateProblem } from "../i18n/problemMessages";

export interface ProblemCatalogEntry {
  /** What happened and why, in one or two plain sentences. */
  message: string;
  /** What the person can do about it. */
  action: string;
}

const TRY_LATER = "Try again in a few minutes. If it keeps happening, contact support with the details below.";
const RELOAD_AND_REDO = "Reload the page to see the latest version, then make your change again.";
const ASK_ADMIN = "Ask an administrator for access if you need it.";

